mechanical_index_check.command:
COGNI_RUN_SAFE_MIN_FREE_PCT=50 RUN_SAFE_PASSTHROUGH_STDIO=1 CRYSTAL_WORKERS=1 TMPDIR=/private/tmp CRYSTAL_CACHE_DIR=/private/tmp/crystal-click-w281-root.gZRr5I/crystal-cache SDKROOT=/Applications/Xcode.app/Contents/Developer/Platforms/MacOSX.platform/Developer/SDKs/MacOSX.sdk /Users/sergey/Projects/Crystal/cogni-ml/scripts/run_safe.sh /usr/bin/ruby 120 1024 -e 'require "json"; require "digest"; require "open3"
p = JSON.parse(File.read(ARGV.fetch(0)))
got, err, st = Open3.capture3("git", "rev-parse", "HEAD")
raise "baseline changed" unless st.success? && err.empty? && got.strip == p.fetch("baseline").fetch("revision")
p.fetch("ownership").fetch("protected_sha256").each { |path,h| raise "protected path changed: #{path}" unless Digest::SHA256.file(path).hexdigest == h }
c = p.fetch("source_state").fetch("candidate"); pairs = c.fetch("files").sort
raise "owned path count differs" unless pairs.size == 21 && c.fetch("count") == 21
pairs.each { |path,h| raise "owned seal drift: #{path}" unless Digest::SHA256.file(path).hexdigest == h }
seal = ->(pairs) { Digest::SHA256.hexdigest(pairs.map { |path,h| "#{path}\t#{h}\n" }.join) }
raise "owned digest differs" unless seal.call(pairs) == c.fetch("digest")
paths = IO.popen(["rg", "--files", "src", "spec/support"], &:read).lines.map(&:strip).sort
src = p.fetch("source_state").fetch("src_support_census")
raise "src/support census differs" unless paths.size == src.fetch("count") && seal.call(paths.map { |path| [path, Digest::SHA256.file(path).hexdigest] }) == src.fetch("digest")
roster = p.fetch("dod").fetch("local_roster"); rs = p.fetch("source_state").fetch("roster_seal")
raise "spec roster seal differs" unless roster.size == rs.fetch("count") && seal.call(roster.sort.map { |path| [path,Digest::SHA256.file(path).hexdigest] }) == rs.fetch("digest")
leaves = []; walk = ->(e) { children = e["subcohorts"] || e["split"]; if children; children.each { |child| walk.call(child) }; else; leaves << e; end }
p.fetch("dod").fetch("release").fetch("cohorts").each { |e| walk.call(e) }
paths = leaves.flat_map { |e| e.fetch("paths") }
raise "release path union differs" unless leaves.size == 6 && paths.size == 113 && paths.uniq.size == 113 && paths.sort == roster.sort
raise "release example sum differs" unless leaves.sum { |e| e.fetch("result").fetch("examples") } == 618 && leaves.all? { |e| r=e.fetch("result"); r["exit_code"] == 0 && %w[failures errors pending].all? { |k| r[k] == 0 } }
p.fetch("native").values_at("debug", "release").each { |m| r=m.fetch("result"); raise "native matrix terminal mismatch" unless r.fetch("exit_code") == 0 && r.fetch("status") == "generated_native_interop_matrix_exact" && r.fetch("cases") == 4 && r.fetch("invocations") == 73 }
puts "Mechanical evidence-index checks passed: baseline, 21 owned byte seals, 656 src/support paths, three protected paths, exact RELEASE 6/113/618 union, and stored native terminals; not a substantive test/compatibility validator"' .landmark/evidence/compact-static-bulk-w281.json
